function my_field(x, y) {

	let vec = createVector((x - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))) / 100, (y - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))) / 100);
	vec.normalize();
	vec.mult(0);

	vec.rotate(PI / 2-PI/10);

	return vec;

}

// === Tab: propagation ===
function propagation(a){

	let cx = a.posx;
	let cy = a.posy;

	let particles = [];
	let num = 10;

	for(let i=0; i<num;i++){


		var x = cx+100*cos(TAU/num*i);
		var y = cy+100*sin(TAU/num*i);
		var radius = a.radius*random();

		let p = particle(x,y,radius);

		particles.push(p);


	}

	return particles;

}

